  }: ExtractProps<typeof this.inputs>): ExtractProps<typeof this.outputs> {
    const widget = {
      id: this.id,
      type: '_FpsWidget',
      placement,
      ...(viewId && viewId !== '' ? { viewId } : {}),
    }
    return { widget }
  }
}

