// Replace functions and circular references
function getJsonSanitizer() {
  const seen = new Set()
  return (_key: string, value: unknown) => {
    if (typeof value === 'object' && value !== null) {
      if (seen.has(value)) {
        return undefined
      }
      seen.add(value)
    } else if (typeof value === 'function') {
      return undefined
    }
    return value
  }
}

