import type { NoodlesProjectJSON } from '../utils/serialization'

// Migration to convert deprecated ReactFlow v11 `parentNode` property to v12+ `parentId`
//
// ReactFlow renamed `parentNode` to `parentId` in v12. This migration:
// 1. Converts any nodes with `parentNode` to use `parentId` instead
// 2. Removes the deprecated `parentNode` property

export async function up(project: NoodlesProjectJSON): Promise<NoodlesProjectJSON> {
  const { nodes, ...rest } = project

  const newNodes = nodes.map(node => {
    // Check if node has the deprecated parentNode property
    const parentNode = (node as any).parentNode
    if (parentNode === undefined) {
      return node
    }

    // Remove parentNode and add parentId if not already present
    const { parentNode: _, ...nodeWithoutParentNode } = node as any

    return {
      ...nodeWithoutParentNode,
      // Use existing parentId if present, otherwise use parentNode value
      parentId: node.parentId || parentNode,
    }
  })

  return {
    ...rest,
    nodes: newNodes,
  }
}

export async function down(project: NoodlesProjectJSON): Promise<NoodlesProjectJSON> {
  const { nodes, ...rest } = project

  // Convert parentId back to parentNode for backwards compatibility
  const newNodes = nodes.map(node => {
    if (!node.parentId) {
      return node
    }

    const { parentId, ...nodeWithoutParentId } = node

    return {
      ...nodeWithoutParentId,
      parentNode: parentId,
    }
  })

  return {
    ...rest,
    nodes: newNodes,
  }
}

import type { NodeJSON } from '@xyflow/react'
import { type MathOpType, mathOps, type OpType, opTypes } from '../operators'
import { edgeId, nodeId } from './id-utils'

export type NodeType = OpType | MathOpType | 'ForLoop'

// Get all available node types (operators, math ops, and special types like ForLoop)
export function getNodeTypeOptions(): NodeType[] {
  return (Object.keys(opTypes) as NodeType[])
    .filter(
      type => type !== 'ForLoopBeginOp' && type !== 'ForLoopEndOp' && type !== 'ForLoopMetaOp'
    )
    .concat(['ForLoop', ...Object.keys(mathOps)])
    .sort()
}

// Convert a string to kebab-case
function toKebabCase(str: string): string {
  return str.replace(/([a-z])([A-Z])/g, '$1-$2').toLowerCase()
}

// Generate an operator ID from its type
function makeOpId(type: OpType, containerId: string): string {
  const baseName = toKebabCase(type.replace(/Op$/g, ''))
  return nodeId(baseName, containerId)
}

// Create nodes and edges for a given operator type
// Returns the nodes and edges that should be added to the graph
export function createNodesForType(
  type: NodeType,
  position: { x: number; y: number },
  currentContainerId: string
): {
  nodes: NodeJSON<unknown>[]
  edges: Array<{
    id: string
    source: string
    target: string
    sourceHandle: string
    targetHandle: string
  }>
} {
  const nodes: NodeJSON<unknown>[] = []
  const edges: Array<{
    id: string
    source: string
    target: string
    sourceHandle: string
    targetHandle: string
  }> = []

  const { x, y } = position

  if (type === 'ForLoop') {
    // ForLoop scope: group node containing ForLoopBeginOp, ForLoopEndOp, and ForLoopMetaOp
    const bodyId = nodeId('for-loop-body', currentContainerId)
    const beginNode = {
      id: makeOpId('ForLoopBeginOp', currentContainerId),
      type: 'ForLoopBeginOp',
      data: undefined,
      parentId: bodyId,
      expandParent: true,
      position: { x: 0, y: 100 },
    }
    const endNode = {
      id: makeOpId('ForLoopEndOp', currentContainerId),
      type: 'ForLoopEndOp',
      data: undefined,
      parentId: bodyId,
      expandParent: true,
      position: { x: 900, y: 100 },
    }
    const metaNode = {
      id: makeOpId('ForLoopMetaOp', currentContainerId),
      type: 'ForLoopMetaOp',
      data: undefined,
      parentId: bodyId,
      expandParent: true,
      position: { x: 450, y: 250 },
    }
    nodes.push({
      id: bodyId,
      type: 'group',
      selectable: false,
      draggable: false,
      style: { width: 1200, height: 400 },
      position: { x, y },
    } as NodeJSON<'group'>)
    nodes.push(beginNode)
    nodes.push(endNode)
    nodes.push(metaNode)
    // Connect ForLoopBegin.item -> ForLoopEnd.item (default connection)
    edges.push({
      id: edgeId({
        source: beginNode.id,
        sourceHandle: 'out.item',
        target: endNode.id,
        targetHandle: 'par.item',
      }),
      source: beginNode.id,
      target: endNode.id,
      sourceHandle: 'out.item',
      targetHandle: 'par.item',
    })
  } else if (type === 'ContainerOp') {
    const id = nodeId('container', currentContainerId)
    const containerInputId = nodeId('container-input', id)
    const containerOutputId = nodeId('container-output', id)
    nodes.push(
      {
        id,
        type,
        data: undefined,
        position: { x, y },
      },
      {
        id: containerInputId,
        type: 'GraphInputOp',
        position: { x: -700, y: 0 },
      },
      {
        id: containerOutputId,
        type: 'GraphOutputOp',
        position: { x: 0, y: 0 },
      }
    )
    const inputSourceHandle = 'par.in'
    const inputTargetHandle = 'par.parentValue'

    const inEdge = {
      source: id,
      sourceHandle: inputSourceHandle,
      target: containerInputId,
      targetHandle: inputTargetHandle,
    }

    const outputSourceHandle = 'out.propagatedValue'
    const outputTargetHandle = 'out.out'

    const outEdge = {
      source: containerOutputId,
      sourceHandle: outputSourceHandle,
      target: id,
      targetHandle: outputTargetHandle,
    }
    edges.push({ ...inEdge, id: edgeId(inEdge) }, { ...outEdge, id: edgeId(outEdge) })
  } else if (mathOps[type]) {
    const operator = mathOps[type] as MathOpType
    nodes.push({
      id: nodeId(operator, currentContainerId),
      type: 'MathOp',
      data: {
        inputs: { operator },
      },
      position: { x, y },
    })
  } else {
    nodes.push({ type, id: makeOpId(type, currentContainerId), position: { x, y } })
  }

  return { nodes, edges }
}

